"use client";

import * as React from "react"

import {
  AttachIcon,
  BellIcon,
  BoldIcon,
  ChatIcon,
  CodeIcon,
  EditIcon,
  InboxIcon,
  MoreHorizontalIcon,
  SearchIcon,
  SendIcon,
  SettingsIcon,
  ThumbsUpIcon,
  UsersIcon,
  XIcon,
} from "@/components/icons"
import { cn } from "@/lib/utils"
import { Button } from "@/registry/web/ui/button"
import { GeneratedAvatarImage } from "@/registry/web/ui/generated-avatar"
import {
  Message,
  MessageAction,
  MessageActions,
  MessageAvatar,
  MessageBubble,
  MessageContent,
  MessageHeader,
  MessageList,
  MessageMarker,
  MessageReaction,
  MessageReactions,
} from "@/registry/web/ui/message"
import { MessageScroller } from "@/registry/web/ui/message-scroller"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarItem,
  SidebarMenu,
  SidebarProvider,
  SidebarRail,
  SidebarRailAvatar,
  SidebarRailGroup,
  SidebarRailItem,
  SidebarRailSpacer,
  SidebarTrigger,
} from "@/registry/web/ui/animated-sidebar"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/registry/web/ui/tooltip"

import {
  CONVERSATIONS,
  ME,
  PEOPLE,
  WORKSPACE,
  formatTime,
  type ChatMessage,
  type Conversation,
  type Person,
} from "./parts/data"

/* ───────────────────────── State ───────────────────────── */

/** Rows from one author closer than this (minutes) fold under the first row's name. */
const GROUP_GAP = 5

function nowMinutes() {
  const d = new Date()
  return d.getHours() * 60 + d.getMinutes()
}

let seq = 0
const newId = () => `local-${Date.now().toString(36)}-${(seq++).toString(36)}`

function mapMessage(list: ChatMessage[], id: string, fn: (m: ChatMessage) => ChatMessage): ChatMessage[] {
  return list.map((m) => (m.id === id ? fn(m) : m.replies ? { ...m, replies: mapMessage(m.replies, id, fn) } : m))
}

function toggleReaction(m: ChatMessage, emoji: string): ChatMessage {
  const reactions = m.reactions ?? []
  const existing = reactions.find((r) => r.emoji === emoji)
  if (!existing) return { ...m, reactions: [...reactions, { emoji, by: [ME] }] }
  const by = existing.by.includes(ME) ? existing.by.filter((p) => p !== ME) : [...existing.by, ME]
  return {
    ...m,
    reactions: by.length ? reactions.map((r) => (r.emoji === emoji ? { ...r, by } : r)) : reactions.filter((r) => r.emoji !== emoji),
  }
}

/** Display name: channels get a `#`, direct messages the other person's name. */
function titleOf(c: Conversation) {
  if (c.kind === "channel") return `#${c.name}`
  return PEOPLE[c.members.find((m) => m !== ME) ?? ME]?.name ?? c.name
}

/* ───────────────────────── Small parts ───────────────────────── */

function Avatar({ person, className }: { person: Person; className?: string }) {
  return <GeneratedAvatarImage seed={person.id} gender={person.gender} className={className} />
}

function Hash() {
  return (
    <span aria-hidden className="grid size-4 place-items-center text-ui font-medium">
      #
    </span>
  )
}

function DmIcon({ person }: { person: Person }) {
  return (
    <span className="relative grid size-4 place-items-center">
      <span className="size-4 overflow-hidden rounded-sm bg-card shadow-raised">
        <Avatar person={person} />
      </span>
      <span
        aria-hidden
        className={cn(
          "absolute -right-0.5 -bottom-0.5 size-1.5 rounded-full ring-2 ring-shell",
          person.status === "online" ? "bg-success" : person.status === "away" ? "bg-warning" : "bg-muted-foreground/50"
        )}
      />
    </span>
  )
}

function IconAction({ label, children, className, ...props }: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button variant="ghost" size="icon-sm" className={cn("text-muted-foreground hover:text-foreground", className)} {...props} aria-label={label}>
            {children}
          </Button>
        }
      />
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  )
}

/** Turns `@Name` into a mention chip, `code` into inline code and **text** into bold. */
function RichText({ text }: { text: string }) {
  const parts = text.split(/(@[A-Za-z]+|`[^`]+`|\*\*[^*]+\*\*)/g)
  return (
    <>
      {parts.map((part, i) => {
        if (part.startsWith("@") && part.length > 1)
          return (
            <span key={i} className="rounded-sm bg-primary/10 px-0.5 font-medium text-primary">
              {part}
            </span>
          )
        if (part.startsWith("`") && part.endsWith("`") && part.length > 2)
          return (
            <code key={i} className="rounded-sm bg-foreground/6 px-1 py-px font-mono text-[0.85em]">
              {part.slice(1, -1)}
            </code>
          )
        if (part.startsWith("**") && part.endsWith("**") && part.length > 4)
          return (
            <strong key={i} className="font-semibold">
              {part.slice(2, -2)}
            </strong>
          )
        return <React.Fragment key={i}>{part}</React.Fragment>
      })}
    </>
  )
}

/* ───────────────────────── Message rows ───────────────────────── */

type RowHandlers = {
  onReact: (id: string, emoji: string) => void
  onOpenThread?: (id: string) => void
}

function MessageRow({ message, grouped, handlers }: { message: ChatMessage; grouped: boolean; handlers: RowHandlers }) {
  const person = PEOPLE[message.author] ?? PEOPLE[ME]!
  const time = formatTime(message.at)
  const replies = message.replies ?? []
  return (
    <Message from={message.author === ME ? "user" : "assistant"} aria-label={`${person.name}, ${time}`}>
      {grouped ? (
        <MessageAvatar placeholder>{time}</MessageAvatar>
      ) : (
        <MessageAvatar>
          <Avatar person={person} />
        </MessageAvatar>
      )}
      <MessageContent>
        {!grouped && (
          <MessageHeader>
            {person.name} <time>{time}</time>
          </MessageHeader>
        )}
        <MessageBubble>
          <RichText text={message.text} />
        </MessageBubble>
        {!!message.reactions?.length && (
          <MessageReactions>
            {message.reactions.map((r) => (
              <MessageReaction
                key={r.emoji}
                emoji={r.emoji}
                count={r.by.length}
                active={r.by.includes(ME)}
                title={r.by.map((p) => PEOPLE[p]?.name ?? p).join(", ")}
                onActiveChange={() => handlers.onReact(message.id, r.emoji)}
              />
            ))}
          </MessageReactions>
        )}
        {handlers.onOpenThread && replies.length > 0 && (
          <button
            type="button"
            onClick={() => handlers.onOpenThread?.(message.id)}
            className="-mx-1 mt-1 flex w-fit cursor-pointer items-center gap-2 rounded-md px-1 py-0.5 text-ui-sm outline-none hover:bg-card hover:shadow-raised focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            <span className="flex -space-x-1">
              {[...new Set(replies.map((r) => r.author))].slice(0, 3).map((id) => (
                <span key={id} className="size-5 overflow-hidden rounded-sm bg-card ring-2 ring-background">
                  <Avatar person={PEOPLE[id]!} />
                </span>
              ))}
            </span>
            <span className="font-medium text-primary">
              {replies.length} {replies.length === 1 ? "reply" : "replies"}
            </span>
            <span className="text-ui-xs text-muted-foreground">Last reply {formatTime(replies[replies.length - 1]!.at)}</span>
          </button>
        )}
        <MessageActions>
          <MessageAction label="Thumbs up" onClick={() => handlers.onReact(message.id, "👍")}>
            <ThumbsUpIcon />
          </MessageAction>
          {handlers.onOpenThread && (
            <MessageAction label="Reply in thread" onClick={() => handlers.onOpenThread?.(message.id)}>
              <ChatIcon />
            </MessageAction>
          )}
          <MessageAction label="More">
            <MoreHorizontalIcon />
          </MessageAction>
        </MessageActions>
      </MessageContent>
    </Message>
  )
}

function Rows({ messages, handlers }: { messages: ChatMessage[]; handlers: RowHandlers }) {
  return (
    <>
      {messages.map((m, i) => {
        const prev = messages[i - 1]
        const grouped = !!prev && prev.author === m.author && m.at - prev.at <= GROUP_GAP
        return <MessageRow key={m.id} message={m} grouped={grouped} handlers={handlers} />
      })}
    </>
  )
}

/* ───────────────────────── Composer ───────────────────────── */

function Composer({ placeholder, onSend, autoFocus }: { placeholder: string; onSend: (text: string) => void; autoFocus?: boolean }) {
  const [value, setValue] = React.useState("")
  const ref = React.useRef<HTMLTextAreaElement>(null)
  const canSend = value.trim().length > 0

  function send() {
    if (!canSend) return
    onSend(value.trim())
    setValue("")
    ref.current?.focus()
  }

  function wrap(mark: string) {
    const el = ref.current
    if (!el) return
    const { selectionStart: s, selectionEnd: e } = el
    const next = value.slice(0, s) + mark + value.slice(s, e) + mark + value.slice(e)
    setValue(next)
    requestAnimationFrame(() => {
      el.focus()
      el.setSelectionRange(s + mark.length, e + mark.length)
    })
  }

  return (
    <form
      data-slot="team-chat-composer"
      onSubmit={(e) => {
        e.preventDefault()
        send()
      }}
      className="frame-xl frame-p-1 flex flex-col bg-card shadow-raised transition-shadow focus-within:ring-2 focus-within:ring-ring/40"
    >
      <textarea
        ref={ref}
        rows={1}
        value={value}
        autoFocus={autoFocus}
        aria-label={placeholder}
        placeholder={placeholder}
        onChange={(e) => setValue(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
            e.preventDefault()
            send()
          }
        }}
        className="field-sizing-content max-h-40 min-h-9 w-full resize-none bg-transparent px-2.5 pt-2 pb-1 text-ui-lg outline-none placeholder:text-muted-foreground"
      />
      <div className="flex items-center gap-0.5">
        <IconAction label="Attach" type="button" className="rounded-inner">
          <AttachIcon />
        </IconAction>
        <IconAction label="Bold" type="button" className="rounded-inner" onClick={() => wrap("**")}>
          <BoldIcon />
        </IconAction>
        <IconAction label="Code" type="button" className="rounded-inner" onClick={() => wrap("`")}>
          <CodeIcon />
        </IconAction>
        <span className="ms-auto me-1.5 hidden text-ui-2xs text-muted-foreground sm:inline">Shift + Enter for a new line</span>
        <Button type="submit" size="icon-sm" variant={canSend ? "default" : "ghost"} disabled={!canSend} className="rounded-inner" aria-label="Send">
          <SendIcon />
        </Button>
      </div>
    </form>
  )
}

/* ───────────────────────── Panes ───────────────────────── */

function ChannelIntro({ conversation }: { conversation: Conversation }) {
  if (conversation.kind === "dm") {
    const other = PEOPLE[conversation.members.find((m) => m !== ME) ?? ME]!
    return (
      <div className="flex flex-col gap-2 px-2 pt-6 pb-4">
        <span className="size-16 overflow-hidden rounded-xl bg-card shadow-raised">
          <Avatar person={other} />
        </span>
        <p className="text-ui-lg font-semibold">{other.name}</p>
        <p className="text-ui text-muted-foreground">
          {other.title}. This is the start of your conversation with {other.name.split(" ")[0]}.
        </p>
      </div>
    )
  }
  return (
    <div className="flex flex-col gap-1.5 px-2 pt-6 pb-4">
      <p className="text-ui-lg font-semibold">#{conversation.name}</p>
      <p className="text-ui text-muted-foreground">
        This is the start of #{conversation.name}. {conversation.topic}.
      </p>
    </div>
  )
}

function ThreadPane({
  conversation,
  parent,
  onClose,
  onReact,
  onSend,
}: {
  conversation: Conversation
  parent: ChatMessage
  onClose: () => void
  onReact: (id: string, emoji: string) => void
  onSend: (text: string) => void
}) {
  const replies = parent.replies ?? []
  return (
    <aside
      aria-label="Thread"
      className="absolute inset-0 z-20 flex min-h-0 flex-col bg-background md:static md:w-88 md:shrink-0 md:border-s md:border-border"
    >
      <header className="flex h-12 shrink-0 items-center gap-2 border-b border-border px-3">
        <span className="text-ui font-semibold">Thread</span>
        <span className="truncate text-ui-sm text-muted-foreground">{titleOf(conversation)}</span>
        <IconAction label="Close thread" className="ms-auto" onClick={onClose}>
          <XIcon />
        </IconAction>
      </header>
      <MessageScroller key={parent.id} className="min-h-0 flex-1" contentClassName="px-2 py-3">
        <MessageList variant="flat">
          <MessageRow message={parent} grouped={false} handlers={{ onReact }} />
          <MessageMarker>
            {replies.length} {replies.length === 1 ? "reply" : "replies"}
          </MessageMarker>
          <Rows messages={replies} handlers={{ onReact }} />
        </MessageList>
      </MessageScroller>
      <div className="shrink-0 p-3 pt-1">
        <Composer placeholder="Reply…" onSend={onSend} />
      </div>
    </aside>
  )
}

/* ───────────────────────── App ───────────────────────── */

export function TeamChatApp({ initial = CONVERSATIONS }: { initial?: Conversation[] }) {
  const [conversations, setConversations] = React.useState(initial)
  const [activeId, setActiveId] = React.useState(initial.find((c) => c.id === "design")?.id ?? initial[0]!.id)
  const [threadId, setThreadId] = React.useState<string | null>(null)
  const [sidebarOpen, setSidebarOpen] = React.useState(true)

  // Phones start with the channel list folded into the rail.
  React.useEffect(() => {
    if (window.matchMedia("(max-width: 767px)").matches) setSidebarOpen(false)
  }, [])

  const active = conversations.find((c) => c.id === activeId)!
  const parent = threadId ? active.messages.find((m) => m.id === threadId) : undefined
  const channels = conversations.filter((c) => c.kind === "channel")
  const dms = conversations.filter((c) => c.kind === "dm")
  const unread = conversations.reduce((n, c) => n + (c.unread ?? 0), 0)

  const update = (id: string, fn: (c: Conversation) => Conversation) =>
    setConversations((list) => list.map((c) => (c.id === id ? fn(c) : c)))

  function open(id: string) {
    setActiveId(id)
    setThreadId(null)
    update(id, (c) => ({ ...c, unread: 0 }))
    if (window.matchMedia("(max-width: 767px)").matches) setSidebarOpen(false)
  }

  const react = (id: string, emoji: string) =>
    update(activeId, (c) => ({ ...c, messages: mapMessage(c.messages, id, (m) => toggleReaction(m, emoji)) }))

  const send = (text: string) =>
    update(activeId, (c) => ({ ...c, messages: [...c.messages, { id: newId(), author: ME, at: nowMinutes(), text }] }))

  const reply = (text: string) =>
    threadId &&
    update(activeId, (c) => ({
      ...c,
      messages: mapMessage(c.messages, threadId, (m) => ({
        ...m,
        replies: [...(m.replies ?? []), { id: newId(), author: ME, at: nowMinutes(), text }],
      })),
    }))

  const me = PEOPLE[ME]!
  const members = active.members.map((id) => PEOPLE[id]!).filter(Boolean)

  return (
    <TooltipProvider>
      <div className="flex h-dvh w-full overflow-hidden bg-shell text-foreground">
        <SidebarProvider open={sidebarOpen} onOpenChange={setSidebarOpen} className="h-full">
          <Sidebar
            aria-label={WORKSPACE.name}
            variant="sidebar"
            panelClassName="border-e-0"
            rail={
              <SidebarRail aria-label="Sections">
                <SidebarRailGroup>
                  <span
                    aria-hidden
                    className="mb-1 grid size-8 place-items-center rounded-lg bg-primary text-ui-xs font-semibold text-primary-foreground shadow-primary"
                  >
                    {WORKSPACE.initials}
                  </span>
                  <SidebarRailItem label="Home" icon={<ChatIcon />} shortcut="⌘1" active badge={unread || undefined} />
                  <SidebarRailItem label="Direct messages" icon={<UsersIcon />} shortcut="⌘2" />
                  <SidebarRailItem label="Activity" icon={<BellIcon />} shortcut="⌘3" />
                  <SidebarRailItem label="Later" icon={<InboxIcon />} shortcut="⌘4" />
                </SidebarRailGroup>
                <SidebarRailSpacer />
                <SidebarRailGroup>
                  <SidebarRailItem label="Settings" icon={<SettingsIcon />} shortcut="⌘," />
                  <SidebarRailAvatar label={me.name} status="online" hint="Active">
                    <Avatar person={me} />
                  </SidebarRailAvatar>
                </SidebarRailGroup>
              </SidebarRail>
            }
          >
            <SidebarHeader className="h-12 flex-row items-center justify-between px-3 py-0">
              <span className="truncate text-ui-lg font-semibold">{WORKSPACE.name}</span>
              <IconAction label="New message">
                <EditIcon />
              </IconAction>
            </SidebarHeader>
            <SidebarContent>
              <SidebarGroup>
                <SidebarGroupLabel>Channels</SidebarGroupLabel>
                <SidebarMenu>
                  {channels.map((c) => (
                    <SidebarItem
                      key={c.id}
                      icon={<Hash />}
                      label={<span className={cn(c.unread && "font-semibold text-foreground")}>{c.name}</span>}
                      tooltip={c.name}
                      badge={c.unread || undefined}
                      isActive={c.id === activeId}
                      onClick={() => open(c.id)}
                    />
                  ))}
                </SidebarMenu>
              </SidebarGroup>
              <SidebarGroup>
                <SidebarGroupLabel>Direct messages</SidebarGroupLabel>
                <SidebarMenu>
                  {dms.map((c) => {
                    const other = PEOPLE[c.members.find((m) => m !== ME) ?? ME]!
                    return (
                      <SidebarItem
                        key={c.id}
                        icon={<DmIcon person={other} />}
                        label={<span className={cn(c.unread && "font-semibold text-foreground")}>{other.name}</span>}
                        tooltip={other.name}
                        badge={c.unread || undefined}
                        isActive={c.id === activeId}
                        onClick={() => open(c.id)}
                      />
                    )
                  })}
                </SidebarMenu>
              </SidebarGroup>
            </SidebarContent>
          </Sidebar>

          <SidebarInset className="min-h-0">
            <div className="relative shell-inset mt-0.75 flex min-h-0 min-w-0 flex-1 overflow-hidden">
              <section aria-label={titleOf(active)} className="flex min-h-0 min-w-0 flex-1 flex-col">
                <header className="flex h-12 shrink-0 items-center gap-2 border-b border-border px-3">
                  <SidebarTrigger />
                  <h1 className="shrink-0 text-ui-lg font-semibold">{titleOf(active)}</h1>
                  {active.topic && <p className="hidden min-w-0 truncate text-ui-sm text-muted-foreground lg:block">{active.topic}</p>}
                  <div className="ms-auto flex items-center gap-1">
                    <Tooltip>
                      <TooltipTrigger
                        render={
                          <button
                            type="button"
                            aria-label={`${members.length} members`}
                            className="flex h-7 cursor-pointer items-center gap-1.5 rounded-md px-1.5 text-ui-sm text-muted-foreground outline-none hover:bg-secondary hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                          >
                            <span className="flex -space-x-1.5">
                              {members.slice(0, 3).map((p) => (
                                <span key={p.id} className="size-5 overflow-hidden rounded-sm bg-card ring-2 ring-background">
                                  <Avatar person={p} />
                                </span>
                              ))}
                            </span>
                            <span className="tabular-nums">{members.length}</span>
                          </button>
                        }
                      />
                      <TooltipContent>{members.map((p) => p.name.split(" ")[0]).join(", ")}</TooltipContent>
                    </Tooltip>
                    <IconAction label="Search">
                      <SearchIcon />
                    </IconAction>
                  </div>
                </header>

                <MessageScroller key={active.id} className="min-h-0 flex-1" contentClassName="mx-auto w-full max-w-3xl px-2 pb-4">
                  <ChannelIntro conversation={active} />
                  <MessageList variant="flat">
                    <MessageMarker>Today</MessageMarker>
                    <Rows messages={active.messages} handlers={{ onReact: react, onOpenThread: setThreadId }} />
                  </MessageList>
                </MessageScroller>

                <div className="mx-auto w-full max-w-3xl shrink-0 px-3 pb-3">
                  <Composer key={active.id} placeholder={`Message ${titleOf(active)}`} onSend={send} />
                </div>
              </section>

              {parent && (
                <ThreadPane conversation={active} parent={parent} onClose={() => setThreadId(null)} onReact={react} onSend={reply} />
              )}
            </div>
          </SidebarInset>
        </SidebarProvider>
      </div>
    </TooltipProvider>
  )
}

/** Seed data for the team chat template. Replace with your own store or API. */

export type Person = { id: string; name: string; gender: "male" | "female"; status: "online" | "away" | "offline"; title: string }

export type Reaction = { emoji: string; by: string[] }

export type ChatMessage = {
  id: string
  author: string
  /** Minutes since midnight, so the seed needs no real dates. */
  at: number
  text: string
  reactions?: Reaction[]
  replies?: ChatMessage[]
}

export type Conversation = {
  id: string
  kind: "channel" | "dm"
  name: string
  topic?: string
  members: string[]
  unread?: number
  messages: ChatMessage[]
}

export const ME = "qinyang"

export const PEOPLE: Record<string, Person> = {
  qinyang: { id: "qinyang", name: "Qinyang Wang", gender: "male", status: "online", title: "Founder" },
  mina: { id: "mina", name: "Mina Park", gender: "female", status: "online", title: "Design" },
  leo: { id: "leo", name: "Leo Tanaka", gender: "male", status: "online", title: "Frontend" },
  sara: { id: "sara", name: "Sara Ruiz", gender: "female", status: "away", title: "Product" },
  omar: { id: "omar", name: "Omar Haddad", gender: "male", status: "offline", title: "Infrastructure" },
  yuki: { id: "yuki", name: "Yuki Sato", gender: "female", status: "online", title: "Docs" },
}

const everyone = Object.keys(PEOPLE)

export const WORKSPACE = { name: "Pane Studio", initials: "PS" }

export const CONVERSATIONS: Conversation[] = [
  {
    id: "general",
    kind: "channel",
    name: "general",
    topic: "Company-wide news and questions",
    members: everyone,
    messages: [
      { id: "g1", author: "sara", at: 9 * 60 + 2, text: "Morning all. Planning review moves to 3pm today." },
      { id: "g2", author: "omar", at: 9 * 60 + 15, text: "Noted. I'll have the infra numbers ready by then.", reactions: [{ emoji: "🙏", by: ["sara"] }] },
      { id: "g3", author: "yuki", at: 10 * 60 + 4, text: "Docs freeze for the release starts Friday, ping me if your page needs a change." },
    ],
  },
  {
    id: "design",
    kind: "channel",
    name: "design",
    topic: "Theme builder, icons and the docs layout",
    members: ["qinyang", "mina", "leo", "yuki"],
    messages: [
      { id: "d1", author: "mina", at: 10 * 60 + 42, text: "The new theme builder is live on the preview deploy." },
      {
        id: "d2",
        author: "mina",
        at: 10 * 60 + 43,
        text: "Try dragging the hue slider, the whole dashboard follows.",
        reactions: [
          { emoji: "🎉", by: ["qinyang", "leo", "yuki", "sara"] },
          { emoji: "👀", by: ["omar", "leo"] },
